	public static Path Create()
	{
		Geometry geometry = Geometry.Parse(SvgPathData);
		geometry.Freeze();
		return new Path
		{
			Data = geometry,
			Stretch = Stretch.Uniform,
			Width = 20.0,
			Height = 20.0,
			SnapsToDevicePixels = true
		};
	}

	public static Brush BrushFor(string themeName) =>
		themeName == "Light"
			? new SolidColorBrush(System.Windows.Media.Color.FromRgb(255, 0, 0))
			: new SolidColorBrush(System.Windows.Media.Color.FromRgb(250, 250, 250));
